/* ---------- Meeting card ---------- */
/* the next meeting, told as it goes: a countdown, "Starting now", the meeting in progress and then over. The track is the
   morning from 10:00 to 12:30 with the meeting on it in the accent tint, its start and end on the block itself. Time that
   has gone is hatched out in neutral grey (the hatch and the tint meet at the now line), and the status chip at the top right
   rolls its minutes. Join stays open while the meeting runs, since people join late, and breathes gently while it is live.
   Every state is the same height. Its content sits 16px in from every edge, and nothing in it grows or shrinks when it is
   pressed (owner, 18 Nov) */
.mtx{width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);container:mtx/inline-size}
.mtx :is(.pill,.ib):active,.mtx .mtx-join.prs{transform:none}
/* the title and the chip share the first line; the time runs under both, so a longer chip never wraps it and every state
   is the same height */
.mtx-h{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);row-gap:2px}
.mtx-t{font-size:14px;font-weight:500;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mtx-sub{grid-row:2;grid-column:1 / -1;font-size:12.5px;color:var(--dm-muted)}
.mtx-st{grid-row:1;grid-column:2;justify-self:end;transition:background .4s cubic-bezier(.22,1,.36,1),color .4s cubic-bezier(.22,1,.36,1)}
.mtx-st>span{display:inline-flex;align-items:center;gap:5px}
.mtx-st .dot{color:var(--dm-ok-mark)}
.mtx-fade{animation:mtxfade .4s cubic-bezier(.22,1,.36,1) both}
@keyframes mtxfade{from{opacity:0}}
/* the minutes roll: each new number comes up from below */
/* the rolling minutes keep the chip's own line, so the number sits on the words' baseline (owner, 17 Nov) */
.mtx-roll{display:inline-grid;overflow:hidden;line-height:inherit;height:1lh}
.mtx-roll i{font-style:normal}
.mtx-roll i.in{animation:mtxroll .32s cubic-bezier(.22,1,.36,1) both}
@keyframes mtxroll{from{transform:translateY(70%);opacity:0}}
/* the track: the morning on a quiet row, the meeting on it */
.mtx-track{position:relative;height:40px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);overflow:hidden}
/* Blueprint's row is the surface itself: its green now line keeps 3:1 on white, not on the row grey */
:root:not([data-style="soft"],[data-style="clean"]) .mtx-track:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:var(--dm-surface)}
.mtx-blk{position:absolute;top:5px;bottom:5px;left:20%;width:60%;display:flex;align-items:center;justify-content:space-between;padding:0 6px;border-radius:calc(5px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-accent-bg);overflow:hidden;font-size:11.5px;font-weight:500;color:var(--dm-fg2)}
/* the start and end sit on the block in small opaque chips of the surface, so they read on the tint and on the hatch alike
   and nothing crosses them: the now line passes under them (owner, 18 Nov). The block's edge is a faint accent line (owner,
   17 Nov: no grey outline) */
.mtx-blk{outline:1px solid color-mix(in srgb,var(--dm-accent-mark) 35%,transparent);outline-offset:-1px}
.mtx-blk>.num{position:relative;z-index:3;padding:0 6px;line-height:18px;border-radius:calc(4px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-surface);color:var(--dm-fg2)}
:root[data-theme="dark"] .mtx-blk>.num{color:var(--dm-fg)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .mtx-blk>.num{color:var(--dm-fg)}}
/* gone: fine 45deg accent lines over the tint, inside the meeting block only, across the part that has run (owner, 17 Nov) */
.mtx-bp{position:absolute;top:0;bottom:0;left:0;background:repeating-linear-gradient(45deg,color-mix(in srgb,var(--dm-accent-mark) 60%,transparent) 0 1px,transparent 1px 6px);transition:width .45s cubic-bezier(.22,1,.36,1)}
.mtx-bp{width:var(--dm-cut,0%)}
.mtx-now{position:absolute;top:0;bottom:0;left:var(--dm-p,0%);width:2px;margin-left:-1px;background:var(--dm-accent-mark);transition:left .45s cubic-bezier(.22,1,.36,1);z-index:2}
.mtx-now i{position:absolute;top:3px;left:50%;width:6px;height:6px;margin-left:-3px;border-radius:50%;background:var(--dm-accent-mark)}
.mtx.done .mtx-now{opacity:0;transition:opacity .4s,left .45s cubic-bezier(.22,1,.36,1)}
/* the footer: who is coming, the link, and Join. The people sit side by side, a little apart, never over each other
   (owner, 18 Nov) */
/* the foot sits under a hairline in Soft and Blueprint (owner, 21 Nov), 16px from it on each side as the card's other gaps;
   Clean's is a foot strip */
.mtx-f{display:flex;align-items:center;gap:var(--dm-s-2);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.mtx-who{display:flex;align-items:center;gap:4px;padding:2px 0}
.mtx-who .av{width:26px;height:26px;font-size:10px}
.mtx-who .mtx-more{background:var(--dm-chip);color:var(--dm-fg2)}
/* a narrow card (a phone) shows the first two people and counts the rest, so the people, the link and Join keep one row
   inside the card */
.mtx-who .mtx-narrow{display:none}
@container mtx (max-width:340px){.mtx-who .mtx-wide{display:none}.mtx-who .mtx-narrow{display:inline-grid}}
/* the copy button's hover a step darker than the row grey, so it reads in light (owner, 17 Nov); once it has copied, the
   link's icon is the green tick for a moment, at the same size */
@media (hover:hover) and (pointer:fine){.mtx-cp:hover{background:color-mix(in srgb,var(--dm-fg) 9%,transparent);color:var(--dm-fg)}}
.mtx-cp.copied{color:var(--dm-ok-mark)!important}
@media (hover:hover) and (pointer:fine){.mtx-cp.copied:hover{color:var(--dm-ok-mark)!important}}
/* Join and its menu as one split button: a very light divider, a chevron that opens the meeting's actions */
.mtx-jg{position:relative;display:flex;flex:none}
.mtx-jg .mtx-join{border-top-right-radius:0;border-bottom-right-radius:0;padding-right:var(--dm-s-3)}
.mtx-jm{position:relative;height:34px;width:30px;padding:0;justify-content:center;border-top-left-radius:0;border-bottom-left-radius:0}
.mtx-jm::before{content:"";position:absolute;left:0;top:9px;bottom:9px;width:1px;background:color-mix(in srgb,var(--dm-on-accent) 30%,transparent)}
.mtx-jm.done{color:var(--dm-on-accent)}
.mtx-pop{min-width:190px}
.mtx-cp{width:34px;height:34px}
.mtx-join{height:34px;padding:0 var(--dm-s-4) 0 6px;gap:var(--dm-s-2);overflow:hidden;justify-content:flex-start;transition:background var(--dm-t-fast),opacity var(--dm-t-fast)}
.mtx-join .mk{width:22px;height:22px;display:grid;place-items:center;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:#fff;flex:none}
.mtx-join .mk .brand{width:15px;height:12.5px}
/* live: Join breathes a step darker and back, slowly; a darker fill keeps its label's contrast where fading it would not */
.mtx.live :is(.mtx-join,.mtx-jm):not(:hover){animation:mtxpulse 2.4s ease-in-out infinite}
@keyframes mtxpulse{50%{background:color-mix(in srgb,var(--dm-accent) 86%,#000)}}
.mtx-join[disabled] .mk{opacity:.5}
@media (prefers-reduced-motion:reduce){.mtx.live :is(.mtx-join,.mtx-jm){animation:none}.mtx-bp,.mtx-now{transition:none}.mtx-roll i.in,.mtx-fade{animation:none}}
/* Clean (owner, 17 and 18 Nov): the meeting and its track on white, the people and actions on an off-white foot strip under a
   hairline. Its content sits 16px in from every edge: the people on the content's edge, and the copy button and Join, split,
   28px pills 8px from the strip's edges, concentric with the card's corner. The track and its block have ordinary round
   corners (they are not controls); the time chips are pills. The block, its lines, the now line, the status chip and the
   people keep their colours. Join is the ink button with a very light divider and no breathing; its menu scales and fades
   from the chevron, and a done action is the green tick */
@keyframes clfade{from{opacity:0}}
@keyframes clroll{from{transform:translateY(60%);opacity:0}}
:root[data-style="clean"] .mtx,:root [data-style="clean"] .mtx,:root [data-style="clean"].mtx{padding:0;gap:0}
:root[data-style="clean"] .mtx-h,:root [data-style="clean"] .mtx-h,:root [data-style="clean"].mtx-h{padding:16px 16px 0}
:root[data-style="clean"] .mtx-t,:root [data-style="clean"] .mtx-t,:root [data-style="clean"].mtx-t{font-size:14px;font-weight:500;letter-spacing:-.01em}
:root[data-style="clean"] .mtx-track,:root [data-style="clean"] .mtx-track,:root [data-style="clean"].mtx-track{margin:16px;height:40px;background:var(--dm-surface);border-radius:var(--dm-r-in);box-shadow:inset 0 0 0 1px var(--dm-line)}
:root[data-style="clean"] .mtx-f,:root [data-style="clean"] .mtx-f,:root [data-style="clean"].mtx-f{position:relative;z-index:3;padding:8px 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-bottom-left-radius:inherit;border-bottom-right-radius:inherit}
:root[data-style="clean"] .mtx-blk,:root [data-style="clean"] .mtx-blk,:root [data-style="clean"].mtx-blk{border-radius:calc(var(--dm-r-in) - 5px)}
:root[data-style="clean"] .mtx-blk>.num,:root [data-style="clean"] .mtx-blk>.num,:root [data-style="clean"].mtx-blk>.num{border-radius:999px;box-shadow:0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .mtx-bp,:root [data-style="clean"] .mtx-bp,:root [data-style="clean"].mtx-bp{transition:width .45s var(--dm-ease)}
:root[data-style="clean"] .mtx-now,:root [data-style="clean"] .mtx-now,:root [data-style="clean"].mtx-now{transition:left .45s var(--dm-ease),opacity .3s var(--dm-ease)}
:root[data-style="clean"] .mtx-fade,:root [data-style="clean"] .mtx-fade,:root [data-style="clean"].mtx-fade{animation:clfade var(--dm-t-fast) var(--dm-ease) both}
:root[data-style="clean"] .mtx-roll i.in,:root [data-style="clean"] .mtx-roll i.in,:root [data-style="clean"].mtx-roll i.in{animation:clroll .3s var(--dm-ease) both}
:root[data-style="clean"] .mtx-cp,:root [data-style="clean"] .mtx-cp,:root [data-style="clean"].mtx-cp{width:28px;height:28px;border-radius:999px}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .mtx-cp:hover,:root [data-style="clean"] .mtx-cp:hover,:root [data-style="clean"].mtx-cp:hover{background:var(--dm-row)}}
:root[data-style="clean"] .mtx .ib:active,:root [data-style="clean"] .mtx .ib:active,:root [data-style="clean"].mtx .ib:active{transform:none}
/* (a step of --dm-ok in the vivid green keeps the copied tick at 3:1 on the off-white strip) */
:root[data-style="clean"] .mtx-cp.copied,:root [data-style="clean"] .mtx-cp.copied,:root [data-style="clean"].mtx-cp.copied{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))!important}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .mtx-cp.copied:hover,:root [data-style="clean"] .mtx-cp.copied:hover,:root [data-style="clean"].mtx-cp.copied:hover{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))!important}}
:root[data-style="clean"] .mtx-jg,:root [data-style="clean"] .mtx-jg,:root [data-style="clean"].mtx-jg{z-index:3}
:root[data-style="clean"] .mtx-jg :is(.mtx-join,.mtx-jm),:root [data-style="clean"] .mtx-jg :is(.mtx-join,.mtx-jm),:root [data-style="clean"].mtx-jg :is(.mtx-join,.mtx-jm){height:28px}
:root[data-style="clean"] .mtx-jg .mtx-join,:root [data-style="clean"] .mtx-jg .mtx-join,:root [data-style="clean"].mtx-jg .mtx-join{border-radius:999px 0 0 999px;padding:0 12px 0 11px;gap:6px}
:root[data-style="clean"] .mtx-jg .mtx-jm,:root [data-style="clean"] .mtx-jg .mtx-jm,:root [data-style="clean"].mtx-jg .mtx-jm{border-radius:0 999px 999px 0;width:28px}
:root[data-style="clean"] .mtx-jm::before,:root [data-style="clean"] .mtx-jm::before,:root [data-style="clean"].mtx-jm::before{top:8px;bottom:8px;background:color-mix(in srgb,var(--dm-on-btn) 26%,transparent)}
:root[data-style="clean"] .mtx-jm.done,:root [data-style="clean"] .mtx-jm.done,:root [data-style="clean"].mtx-jm.done{color:var(--dm-ok-mark)}
/* Join's menu is Clean's popover: 22px corners, its rows 6px in with Clean's 10px rows and the one gliding hover (hoverGlide) */
:root[data-style="clean"] .mtx-pop,:root [data-style="clean"] .mtx-pop,:root [data-style="clean"].mtx-pop{padding:6px;border-radius:var(--dm-r-card)}
/* on the white ink of dark mode the green tick is a deeper step, so it keeps 3:1 */
:root[data-style="clean"][data-theme="dark"] .mtx-jm.done,:root[data-theme="dark"] [data-style="clean"] .mtx-jm.done,:root[data-theme="dark"] [data-style="clean"].mtx-jm.done{color:color-mix(in srgb,var(--dm-ok-mark) 60%,#000)}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) .mtx-jm.done,:root:not([data-theme="light"]) [data-style="clean"] .mtx-jm.done,:root:not([data-theme="light"]) [data-style="clean"].mtx-jm.done{color:color-mix(in srgb,var(--dm-ok-mark) 60%,#000)}}
/* the call's logo stands on its own beside Join, the size of the word, with no white tile behind it (owner, 21 Nov: "use
   icon without white bg on clean style") */
:root[data-style="clean"] .mtx-join .mk,:root [data-style="clean"] .mtx-join .mk,:root [data-style="clean"].mtx-join .mk{width:14px;height:14px;border-radius:0;background:none}
:root[data-style="clean"] .mtx-join .mk .brand,:root [data-style="clean"] .mtx-join .mk .brand,:root [data-style="clean"].mtx-join .mk .brand{width:14px;height:11.7px}
:root[data-style="clean"] .mtx.live :is(.mtx-join,.mtx-jm),:root [data-style="clean"] .mtx.live :is(.mtx-join,.mtx-jm),:root [data-style="clean"].mtx.live :is(.mtx-join,.mtx-jm){animation:none}
/* Join and its chevron are one split button: a press sinks its fill (the ink's pressed shade) and never scales one half */
:root[data-style="clean"] .mtx .mtx-jg .pill:is(.mtx-join,.mtx-jm):active,:root [data-style="clean"] .mtx .mtx-jg .pill:is(.mtx-join,.mtx-jm):active,:root [data-style="clean"].mtx .mtx-jg .pill:is(.mtx-join,.mtx-jm):active{transform:none}
/* a phone: the foot strip's pieces close up a little, so Join keeps its room beside the people as its words change */
@media (max-width:400px){.mtx-who{gap:3px}.mtx-who .av{width:24px;height:24px}:root[data-style="clean"] .mtx-f,:root [data-style="clean"] .mtx-f,:root [data-style="clean"].mtx-f{gap:6px}:root[data-style="clean"] .mtx-jg .mtx-join,:root [data-style="clean"] .mtx-jg .mtx-join,:root [data-style="clean"].mtx-jg .mtx-join{padding:0 10px 0 9px;gap:6px}}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] :is(.mtx-bp,.mtx-now),:root [data-style="clean"] :is(.mtx-bp,.mtx-now),:root [data-style="clean"]:is(.mtx-bp,.mtx-now){transition:none}:root[data-style="clean"] :is(.mtx-fade,.mtx-roll i.in),:root [data-style="clean"] :is(.mtx-fade,.mtx-roll i.in),:root [data-style="clean"]:is(.mtx-fade,.mtx-roll i.in){animation:none}}

DM.def('meeting-card', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{([\w-]+)\}/g, (m, k) => k === 'meet' ? BRAND.meet : I(k, k === 'clock' || k === 'chev-d' ? 'xs' : 's'));
  // the row runs 10:15 to 11:30 in minutes of the day; the meeting is 10:30 to 11:15, 45 minutes
  const FROM = 615, TO = 690, AT = 630, END = 675, URL = 'https://meet.google.com/nax-wqkf-stu';
  const pc = m => Math.min(100, Math.max(0, (m - FROM) / (TO - FROM) * 100));
  const clock = m => `${Math.floor(m / 60)}:${String(m % 60).padStart(2, '0')}`;
  const root = $('.mtx', r), st = $('.mtx-st', r), track = $('.mtx-track', r), blk = $('.mtx-blk', r), join = $('.mtx-join', r), jm = $('.mtx-jm', r), cp = $('.mtx-cp', r);
  const phase = m => m < AT ? 'soon' : m === AT ? 'start' : m < END ? 'live' : 'done';
  let was = 'soon', num = 10;
  // the chip: a new state fades in; within a state only the minutes change, and they roll
  const chip = (cls, inner) => { st.className = 'tag mtx-st' + (cls ? ' ' + cls : ''); st.innerHTML = `<span class="mtx-fade">${inner}</span>`; };
  const roll = n => { const el = $('.mtx-roll', st); if (el && n !== num) el.innerHTML = `<i class="in">${n}</i>`; num = n; };
  const set = m => {
    const ph = phase(m), p = pc(m);
    root.style.setProperty('--dm-p', p + '%'); track.style.setProperty('--dm-p', p + '%');
    blk.style.setProperty('--dm-cut', Math.min(100, Math.max(0, (m - AT) / (END - AT) * 100)) + '%');
    const n = ph === 'soon' ? AT - m : END - m;
    if (ph !== was){
      if (ph === 'soon') chip('', `${I('clock', 'xs')}In <span class="mtx-roll num"><i>${n}</i></span> min`);
      if (ph === 'start') chip('ok', '<i class="dot"></i>Starting now');
      if (ph === 'live') chip('ok', `<i class="dot"></i>Live, <span class="mtx-roll num"><i>${n}</i></span> min left`);
      if (ph === 'done') chip('', 'Ended');
      num = n;
    } else roll(n);
    was = ph;
    root.classList.toggle('live', ph === 'start' || ph === 'live');
    root.classList.toggle('done', ph === 'done');
    join.disabled = jm.disabled = ph === 'done';
    track.setAttribute('aria-label', ph === 'done' ? 'The meeting ran 10:30 to 11:15 and has ended' : `Now ${clock(m)}. The meeting runs 10:30 to 11:15`);
  };
  set(620);
  // the button is as wide as its words and eases to its new width when they change, keeping no room for a longer one (owner, 18 Nov)
  const easeW = el => { let w = 0, busy = null; const ro = new ResizeObserver(() => { if (busy) return; const w1 = el.getBoundingClientRect().width;
    if (!REDUCE && w && Math.abs(w1 - w) > .5){ busy = el.animate([{ width:w + 'px' }, { width:w1 + 'px' }], { duration:340, easing:'cubic-bezier(.23,1,.32,1)' }); busy.finished.catch(() => {}).then(() => { busy = null; w = el.getBoundingClientRect().width; }); } w = w1; });
    ro.observe(el); c.offs.push(() => ro.disconnect()); };
  easeW(join);
  join.onclick = () => {
    join.classList.add('prs'); c.later(110, () => join.classList.remove('prs'));
    const lb = $('.lb', join); swap(lb, 'Opening Meet'); c.later(1600, () => swap(lb, 'Join'));
  };
  cp.onclick = () => copied(cp, URL, 'Copied');
  // the meeting's actions: the chevron flashes a check and says what happened
  const jmIc = jm.innerHTML;
  $$('.mtx-pop .mi', r).forEach(b => b.addEventListener('click', () => {
    if (b.dataset.a === 'Invitation copied'){ try { navigator.clipboard.writeText(`Pricing review, today 10:30 to 11:15\n${URL}`).catch(() => {}); } catch(e){} }
    clearTimeout(jm._t); c.later(140, () => { jm.innerHTML = I('check', 'xs'); jm.classList.add('done'); jm.dataset.tip = b.dataset.a; showTip(jm);
      jm._t = setTimeout(() => { jm.innerHTML = jmIc; jm.classList.remove('done'); delete jm.dataset.tip; if (tipFor === jm) hideTip(true); }, 1500); });
  }));
  c.offs.push(() => clearTimeout(jm._t));
  const who = $('.mtx-who', r);
  // the preview: the countdown, "Starting now", the meeting going by with the gone part hatched, then over
  c.story(async s => {
    await s.beat(2);
    for (let m = 621; m <= AT; m++){ await s.beat(1); set(m); }
    await s.beat(4);
    for (let m = AT + 3; m <= 651; m += 3){ await s.beat(1.2); set(m); }
    who.classList.add('hv'); await s.point($$('.av', who)[1]); await s.beat(3);
    who.classList.remove('hv'); await s.tap(cp); await s.beat(3);
    s.away();
    for (let m = 654; m <= END; m += 3){ await s.beat(1.2); set(m); }
    await s.beat(5);
  });
});
